// Bundles the Vercel function (server/vercelEntry.ts and all of server/ + src/lib it uses) into api/index.js.
// The server code uses extensionless and .ts imports, which Vite and tsx resolve but Vercel's plain Node runtime
// does not ("Cannot find module '/var/task/server/app'"). One bundled file avoids that. npm packages stay
// external; Vercel traces and ships them from node_modules. api/index.js is generated: do not edit or commit it.
import { build } from 'esbuild';

await build({
  entryPoints: ['server/vercelEntry.ts'],
  outfile: 'api/index.js',
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  packages: 'external',
  sourcemap: false,
  logLevel: 'warning',
  banner: { js: '// Generated by scripts/bundle-vercel-api.mjs from server/vercelEntry.ts. Do not edit.' },
});
console.log('api/index.js bundled from server/vercelEntry.ts.');
